'use client';

import React from 'react';

interface CodingSprintSectionProps {
  onStartSprint?: () => void;
  onStartConquest?: () => void;
}

const CARDS = [
  {
    id: 'sprint',
    label: '100 Days Coding Sprint',
    description: 'Level up your skills daily with our 100-Day Coding Sprint',
    width: 499,
    crop: { x: 24, y: 6, width: 581, height: 323 },
    underlines: [{ x1: 49, y: 85, x2: 209 }, { x1: 49, y: 124, x2: 307 }],
    background: '#dceafb',
  },
  {
    id: 'conquest',
    label: 'Code Conquest',
    description: 'Pick your topics, set your difficulty, and master key concepts with ease!',
    width: 490,
    crop: { x: 630, y: 6, width: 581, height: 323 },
    underlines: [{ x1: 655, y: 85, x2: 750 }, { x1: 655, y: 124, x2: 842 }],
    background: '#fff0bd',
  },
] as const;

export const CodingSprintSection: React.FC<CodingSprintSectionProps> = ({
  onStartSprint,
  onStartConquest,
}) => {
  const handleStart = (id: (typeof CARDS)[number]['id']) => {
    if (id === 'sprint') onStartSprint?.();
    else onStartConquest?.();
  };

  return (
    <section aria-label="Coding practice"
      className="mx-auto my-5 w-full min-w-0 max-w-[980px] px-2 sm:px-4 select-none">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 sm:gap-5 w-full">
        {CARDS.map((card) => (
          <button key={card.id} type="button" onClick={() => handleStart(card.id)}
            aria-label={`${card.label} — ${card.description}. Start now`}
            className="group relative block w-full min-w-0 cursor-pointer overflow-hidden rounded-[20px] border-0 p-0 text-left shadow-[0_2px_10px_rgba(0,0,0,0.05)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#0073e6] focus-visible:ring-offset-4 sm:rounded-[22px]"
            style={{ backgroundColor: card.background }}>
            <span className="relative block w-full overflow-hidden">
              {/* Keep the original card ratios: 499/284 and 490/284. */}
              <svg viewBox={`0 0 ${card.width} 284`}
                className="block h-auto w-full select-none pointer-events-none" aria-hidden="true">
                <svg x="0" y="0" width={card.width} height={284}
                  viewBox={`${card.crop.x} ${card.crop.y} ${card.crop.width} ${card.crop.height}`}
                  preserveAspectRatio="none" overflow="hidden">
                  <image href={IMAGE} width={IMAGE_WIDTH} height={IMAGE_HEIGHT} />
                  <g className="opacity-0 transition-opacity duration-150 group-hover:opacity-100 group-focus-visible:opacity-100">
                    {card.underlines.map((line, index) => (
                      <line key={index} x1={line.x1} y1={line.y} x2={line.x2} y2={line.y}
                        stroke="#222222" strokeWidth={2.4} strokeLinecap="round" />
                    ))}
                  </g>
                </svg>
              </svg>
            </span>
          </button>
        ))}
      </div>
    </section>
  );
};

export default CodingSprintSection;

const IMAGE_WIDTH = 1242;
const IMAGE_HEIGHT = 338;
const IMAGE = "data:image/png;base64,";
